// A PRICE LIST, not a capability. Found while gridding the receiver axes
// for 4112 and DECLINED there, because it is a different path with a
// different owner and taking it would have widened that change past what
// its evidence covers.
//
// `o.m()` where `o` is an object LITERAL whose fields have no one common
// type lowers to a typed RECORD with a function-typed field, and the call
// through that field DROPS the receiver: `this` is undefined inside `m`.
// Node binds `o`. There is no diagnostic, no fence and nothing in the trap
// census -- it is a wrong ANSWER, which is the failure mode this project
// has learned to fear most.
//
// It is NOT the bug 4111/4112 fix. That one was the checked-dynamic path
// (`scr_dyn_call` with no receiver, the ambient window leaking the
// enclosing `this`); this one never reaches the dyn tier at all. Measured
// identical on base fbabf176 and on the branch, both backends.
//
// `ctor` below is the control that says the dyn tier is fine: the SAME
// member shape on a CONSTRUCTED object binds correctly on both sides.
"use strict";

exports.lit = function () {
    var o = { tag: "L", m: function () { return this === undefined ? "undefined" : "self " + String(this.tag); } };
    return String(o.m());
};

exports.arrEl = function () {
    var a = [{ tag: "A0", m: function () { return this === undefined ? "undefined" : "self " + String(this.tag); } }];
    return String(a[0].m());
};

function C() {
    this.tag = "C";
    this.m = function () { return this === undefined ? "undefined" : "self " + String(this.tag); };
}
exports.ctor = function () { return String(new C().m()); };
